const fs = await import('node:fs');
const path = await import('node:path');
const gulp = (await import('gulp')).default;
const yaml = globalThis.yaml;
const inputPath = globalThis.inputPath;
const outputPath = globalThis.outputPath;

const dir = path.dirname(inputPath);
const file = path.basename(inputPath);
const glob = path.join(dir, file);

const stream = gulp.src(glob).pipe(yaml({ safe: true }));

const chunks = [];
await new Promise((resolve, reject) => {
  stream.on('data', (chunk) => {
    chunks.push(chunk);
  });
  stream.on('end', () => {
    resolve();
  });
  stream.on('error', (err) => {
    reject(err);
  });
});

if (chunks.length === 0) throw new Error('No data produced by gulp-yaml');

const content = Buffer.concat(chunks).toString('utf8');

// Ensure output directory exists
const outDir = path.dirname(outputPath);
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

fs.writeFileSync(outputPath, content, 'utf8');
globalThis.resultPath = outputPath;
